char* compress(char* text) {
    int n = strlen(text), i = 0, w = 0;
    char* out = malloc(n + 1);
    while (i < n) {
        int j = i;
        while (j < n && text[j] == text[i]) j++;
        out[w++] = text[i];
        if (j - i > 1) w += sprintf(out + w, "%d", j - i);
        i = j;
    }
    out[w] = '\0';
    return out;
}
